SELECT "sk_timeid", "timevalue", "hourid", "hourdesc", "minuteid", "minutedesc", "secondid", "seconddesc", "markethoursflag", "officehoursflag" FROM (SELECT TRY_CAST((CAST(t.SK_TimeID AS INT)) AS INT) AS "sk_timeid", TRY_CAST((TRY_CAST(t.TimeValue AS TIME)) AS TIME) AS "timevalue", TRY_CAST((t.HourID) AS DECIMAL(2)) AS "hourid", TRY_CAST((t.HourDesc) AS TEXT) AS "hourdesc", TRY_CAST((t.MinuteID) AS DECIMAL(2)) AS "minuteid", TRY_CAST((CAST(t.MinuteDesc AS TEXT)) AS TEXT) AS "minutedesc", TRY_CAST((t.SecondID) AS DECIMAL(2)) AS "secondid", TRY_CAST((t.SecondDesc) AS TEXT) AS "seconddesc", TRY_CAST((TRY_CAST(t.MarketHoursFlag AS BOOLEAN)) AS BOOLEAN) AS "markethoursflag", TRY_CAST((CASE WHEN LOWER(t.OfficeHoursFlag) = 'true' THEN TRUE WHEN LOWER(t.OfficeHoursFlag) = 'false' THEN FALSE ELSE NULL END) AS BOOLEAN) AS "officehoursflag" FROM "Source"."Time" AS t);
